style.css:
@-moz-document regexp(".*") {
/* 1. Global Backgrounds and Text Base (Wemmbu Dark Grey/Purple Theme) */
    body, html, div, main, section, article {
        background-color: #14111a !important; /* Deep Onyx Purple Black */
        color: #ffffff !important; /* Pure White Main Text */
        font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif !important;
    }

    /* 2. Secondary Containers / Cards / Sidebars */
    nav, header, footer, aside, .sidebar, .card, .box, [class*="container"], [class*="header"], [class*="footer"] {
        background-color: #1c1826 !important; /* Mid-tone Demon Purple */
        border-color: #3b2d54 !important; /* Subtle purple border */
    }

    /* 3. Links and Neon Purple Highlights (Wemmbu Glow) */
    a, h1, h2, h3, h4, h5, h6, strong, [class*="title"] {
        color: #b088ff !important; /* Bright Neon Accent Purple */
        transition: color 0.2s ease-in-out !important;
    }

    /* Link Hover effect */
    a:hover {
        color: #dfc9ff !important; /* Lighter white-purple glow on hover */
        text-shadow: 0 0 8px rgba(176, 136, 255, 0.6) !important;
    }

    /* 4. Inputs, Buttons, and Interactive Elements */
    input, textarea, select, button, [role="button"] {
        background-color: #251f33 !important;
        color: #ffffff !important;
        border: 2px solid #6c42be !important; /* Wemmbu signature purple borders */
        border-radius: 6px !important;
        padding: 6px 12px !important;
    }

    /* Button and Input Focus Glows */
    input:focus, textarea:focus, button:hover {
        background-color: #312845 !important;
        border-color: #a473ff !important;
        box-shadow: 0 0 10px rgba(164, 115, 255, 0.5) !important;
        outline: none !important;
        cursor: pointer !important;
    }

    /* 5. Scrollbar Tweaks to match the aesthetic */
    ::-webkit-scrollbar {
        width: 10px !important;
        height: 10px !important;
    }
    ::-webkit-scrollbar-track {
        background: #14111a !important;
    }
    ::-webkit-scrollbar-thumb {
        background: #473666 !important;
        border-radius: 5px !important;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #6c42be !important;
    }

    /* 6. Muting overly bright images or backgrounds to keep the vibe dark */
    img {
        opacity: 0.95 !important;
    }
}
